+import {indexSitesFixesConfig, getSitesFixesFor} from '../../../../src/generators/utils/parse';
+import type {SitesFixesParserOptions} from '../../../../src/generators/utils/parse';
+
+// ENG-406: parser should ignore Base64 padding within CSS
+// The bug: indexSitesFixesConfig uses an unanchored delimiter regex /\s*={2,}\s*/gm
+// which matches "==" inside Base64-encoded data URLs (e.g. base64,ABC==),
+// splitting what should be one record into multiple at the wrong offsets.
+// The fix: anchor the regex to full lines only: /^\s*={2,}\s*$/gm
+
+test('Base64 padding in CSS is not treated as a record delimiter', () => {
+    interface TestFix {
+        url: string[];
+        css: string;
+    }
+
+    const directiveMap: {[key: string]: keyof TestFix} = {
+        CSS: 'css',
+    };
+
+    const options: SitesFixesParserOptions<TestFix> = {
+        commands: Object.keys(directiveMap),
+        getCommandPropName: (command) => directiveMap[command],
+        parseCommandValue: (_, value) => value.trim(),
+    };
+
+    // This config has a Base64 data URL with "==" padding inside a CSS value.
+    // The "==" on the same line as other CSS must NOT be treated as a delimiter.
+    const base64CssLine = '.icon { background: url(data:image/png;base64,iVBORw0KGgoAAAANSUhEUg==); }';
+    const config = [
+        '*',
+        '',
+        'CSS',
+        base64CssLine,
+        '',
+        '==================',
+        '',
+        'example.com',
+        '',
+        'CSS',
+        '.other { color: red; }',
+        ''
+    ].join('\n');
+
+    const index = indexSitesFixesConfig<TestFix>(config);
+    const fixes = getSitesFixesFor('example.com', config, index, options);
+
+    // With the bug, the "==" inside base64,iVBORw0KGgoAAAANSUhEUg== causes the
+    // indexer to split the first record early, corrupting offsets for all subsequent
+    // records. The fix for 'example.com' either becomes empty or gets wrong content.
+    // After the fix is applied, we must get exactly these two records:
+    expect(fixes).toEqual([
+        {
+            url: ['*'],
+            css: base64CssLine,
+        },
+        {
+            url: ['example.com'],
+            css: '.other { color: red; }',
+        },
+    ]);
+});
